"""Check whether brackets in a string are balanced.

Only (), [] and {} are considered. Text inside double-quoted strings is
ignored; inside a string a backslash escapes the next character, so \" does
not end the string. An unterminated string makes the input unbalanced.
"""

_PAIRS = {')': '(', ']': '[', '}': '{'}
_OPENERS = set('([{')


def balanced(s):
    stack = []
    in_string = False
    escape = False

    for c in s:
        if in_string:
            if escape:
                escape = False
            elif c == '\\':
                escape = True
            elif c == '"':
                in_string = False
            continue

        if c == '"':
            in_string = True
        elif c in _OPENERS:
            stack.append(c)
        elif c in _PAIRS:
            if not stack or stack.pop() != _PAIRS[c]:
                return False

    return not in_string and not stack
